import { PaypalButtonStyleColorOption, PaypalStyleOptions } from './paypal';

export const VenmoButtonImage = {
    [PaypalButtonStyleColorOption.WHITE]:
        'data:image/svg+xml;base64,',
    [PaypalButtonStyleColorOption.BLUE]:
        'data:image/svg+xml;base64,',
};

const getBraintreeVenmoButtonStyle = (styles: PaypalStyleOptions): Record<string, string> => {
    const { color, height } = styles;

    const colorParser = (c: string) => {
        if (c === PaypalButtonStyleColorOption.WHITE) {
            return '#FFFFFF';
        }

        return '#3D95CE';
    };

    return {
        backgroundColor: colorParser(color || ''),
        backgroundPosition: '50% 50%',
        backgroundSize: '80px auto',
        backgroundImage: `url("${
            VenmoButtonImage[
                color === PaypalButtonStyleColorOption.WHITE
                    ? PaypalButtonStyleColorOption.BLUE
                    : PaypalButtonStyleColorOption.WHITE
            ]
        }")`,
        backgroundRepeat: 'no-repeat',
        borderRadius: '4px',
        cursor: 'pointer',
        transition: '0.2s ease',
        minHeight: `${height || 40}px`,
        minWidth: '150px',
        height: '100%',
        border: color === PaypalButtonStyleColorOption.WHITE ? '1px solid black' : 'none',
    };
};

export default getBraintreeVenmoButtonStyle;
